204: /* ------------------------------ audio ------------------------------ */
205: let AC = null, masterGain = null, noiseBuffer = null;
206: function ensureAudio() {
207:   if (AC) { if (AC.state === 'suspended') AC.resume(); return; }
208:   const C = window.AudioContext || window.webkitAudioContext;
209:   if (!C) return;
210:   AC = new C();
211:   masterGain = AC.createGain();
212:   masterGain.gain.value = profile.muted ? 0 : 0.34;
213:   masterGain.connect(AC.destination);
214:   const len = Math.floor(AC.sampleRate * 1.2);
215:   noiseBuffer = AC.createBuffer(1, len, AC.sampleRate);
216:   const d = noiseBuffer.getChannelData(0);
217:   for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
218: }
219: function setMuted(m, silent) {
220:   profile.muted = !!m;
221:   if (masterGain) masterGain.gain.value = m ? 0 : 0.34;
222:   el.btnMute.classList.toggle('muted', !!m);
223:   el.btnMute.setAttribute('aria-pressed', m ? 'true' : 'false');
224:   el.btnMute.setAttribute('aria-label', m ? 'Unmute sound' : 'Mute sound');
225:   el.btnMute.title = m ? 'Unmute sound' : 'Mute sound';
226:   if (!silent) { saveSoon(); if (!m) ensureAudio(); }
227: }
228: function blip(freq, dur, type = 'sine', vol = 0.18, slide = 0, delay = 0) {
229:   if (!AC || profile.muted) return;
230:   const t0 = AC.currentTime + delay;
231:   const o = AC.createOscillator(), gn = AC.createGain();
232:   o.type = type;
233:   o.frequency.setValueAtTime(freq, t0);
234:   if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(35, freq + slide), t0 + dur);
235:   gn.gain.setValueAtTime(0.0001, t0);
236:   gn.gain.exponentialRampToValueAtTime(vol, t0 + 0.006);
237:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
238:   o.connect(gn); gn.connect(masterGain);
239:   o.start(t0); o.stop(t0 + dur + 0.03);
240: }
241: function noiseBurst(dur, vol = 0.18, freq = 1100, delay = 0, type = 'bandpass', slideTo) {
242:   if (!AC || profile.muted || !noiseBuffer) return;
243:   const t0 = AC.currentTime + delay;
244:   const src = AC.createBufferSource();
245:   src.buffer = noiseBuffer;
246:   const f = AC.createBiquadFilter();
247:   f.type = type; f.frequency.setValueAtTime(freq, t0);
248:   if (slideTo) f.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
249:   const gn = AC.createGain();
250:   gn.gain.setValueAtTime(vol, t0);
251:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
252:   src.connect(f); f.connect(gn); gn.connect(masterGain);
253:   src.start(t0); src.stop(t0 + dur + 0.02);
254: }
