333: /* ------------------------------ layout ------------------------------ */
334: function computeLayout() {
335:   const prevW = W, prevH = H, prevFloor = floorY;
336:   W = window.innerWidth;
337:   H = window.innerHeight;
338:   DPR = Math.min(window.devicePixelRatio || 1, 2);
339:   el.canvas.width = Math.round(W * DPR);
340:   el.canvas.height = Math.round(H * DPR);
341:   el.canvas.style.width = W + 'px';
342:   el.canvas.style.height = H + 'px';
343: 
344:   isTouch = window.matchMedia('(pointer: coarse)').matches || (navigator.maxTouchPoints || 0) > 0;
345:   document.body.classList.toggle('touch', isTouch);
346:   S = clamp(Math.sqrt(W * H) / 860, 0.66, 1.3);
347:   apron = isTouch ? clamp(H * 0.27, 96, 134) : clamp(H * 0.075, 44, 66);
348:   arenaTop = isTouch ? 78 : 96;
349:   floorY = H - apron;
350:   const margin = isTouch ? 14 : 24;
351:   arena = { left: margin, right: W - margin, top: arenaTop, bottom: floorY };
352: 
353:   skyGrad = ctx.createLinearGradient(0, 0, 0, Math.max(200, floorY));
354:   skyGrad.addColorStop(0, '#3a1e66');
355:   skyGrad.addColorStop(0.38, '#8a3a8d');
356:   skyGrad.addColorStop(0.64, '#f56d73');
357:   skyGrad.addColorStop(0.85, '#ffb35e');
358:   skyGrad.addColorStop(1, '#ffe29a');
359:   vignetteGrad = ctx.createRadialGradient(W / 2, H * 0.45, Math.min(W, H) * 0.2, W / 2, H * 0.5, Math.max(W, H) * 0.78);
360:   vignetteGrad.addColorStop(0, 'rgba(20,8,35,0)');
361:   vignetteGrad.addColorStop(0.72, 'rgba(20,8,35,0.12)');
362:   vignetteGrad.addColorStop(1, 'rgba(20,8,35,0.55)');
363: 
364:   rebuildDecor();
365:   if (prevW && (prevW !== W || prevH !== H)) {
366:     const sx = W / prevW;
367:     const sy = H / prevFloor;
368:     for (const p of players) {
369:       p.x *= sx;
370:       p.y = prevFloor ? p.y * sy : floorY;
371:       p.y = Math.min(p.y, floorY);
372:     }
373:     for (const b of balls) { b.x *= sx; b.y *= sy; }
374:     for (const pk of pickups) { pk.x *= sx; pk.y = Math.min(pk.y * sy, floorY - 20); }
375:     if (state === 'title' || state === 'matchEnd') generatePlatforms();
376:   }
377: }
