424: function rebuildDecor() {
425:   stars = Array.from({ length: 34 }, () => ({
426:     x: rand(0, W), y: rand(arenaTop, floorY * 0.45), r: rand(0.5, 1.6) * Math.max(0.8, S),
427:     ph: rand(0, TAU), sp: rand(0.4, 1.6),
428:   }));
429:   clouds = Array.from({ length: 4 }, (_, i) => ({
430:     x: rand(-100, W), y: arenaTop + rand(30, Math.max(90, (floorY - arenaTop) * 0.35)),
431:     s: rand(0.7, 1.35) * clamp(S, 0.7, 1.2), sp: rand(3, 9), a: rand(0.1, 0.24), ph: rand(0, TAU),
432:   }));
433:   buildingsFar = []; buildingsNear = [];
434:   let x = -30;
435:   while (x < W + 60) {
436:     const w = rand(34, 88) * clamp(S, 0.8, 1.2);
437:     const h = rand(70, 190) * clamp(S, 0.8, 1.2);
438:     buildingsFar.push({ x, w, h, seed: rand(0, 100) });
439:     x += w + rand(5, 18);
440:   }
441:   x = -40;
442:   while (x < W + 60) {
443:     const w = rand(44, 110) * clamp(S, 0.8, 1.2);
444:     const h = rand(40, 130) * clamp(S, 0.8, 1.2);
445:     buildingsNear.push({ x, w, h, seed: rand(0, 100) });
446:     x += w + rand(8, 24);
447:   }
448:   ambientConfetti = Array.from({ length: 20 }, () => ({
449:     x: rand(0, W), y: rand(arenaTop, floorY), vy: rand(8, 26), vx: rand(-8, 8),
450:     rot: rand(0, TAU), spin: rand(-2, 2), w: rand(4, 8) * clamp(S, 0.7, 1.2),
451:     color: pick(['#ffd23f', '#ff5d5d', '#2ec4b6', '#ff8fab', '#fff4d8']), ph: rand(0, TAU),
452:   }));
453: }
