379: function generatePlatforms() {
380:   const bw = arena.right - arena.left;
381:   const mirror = Math.random() < 0.5;
382:   const w = [
383:     clamp(250 * S, bw * 0.22, bw * 0.34),
384:     clamp(215 * S, bw * 0.20, bw * 0.30),
385:     clamp(185 * S, bw * 0.17, bw * 0.26),
386:   ];
387: 
388:   // Keep the lowest ledge above a brawler's head (plus badge) and keep every
389:   // step within a single jump. Short/landscape screens get fewer ledges rather
390:   // than a cramped stack that clips through the fighters.
391:   const step = 125 * S;
392:   const maxRise = Math.max(step, floorY - (arena.top + 54 * S));
393:   let levels = 1;
394:   if (maxRise >= step * 2) levels = 2;
395:   if (maxRise >= step * 3) levels = 3;
396: 
397:   // Chain the platforms horizontally so each one overlaps the next.
398:   const xs = [arena.left + bw * 0.05];
399:   for (let i = 1; i < levels; i++) {
400:     xs[i] = Math.min(xs[i - 1] + w[i - 1] - w[i] * 0.34, arena.right - w[i] - 10);
401:   }
402: 
403:   platforms = [];
404:   for (let i = 0; i < levels; i++) {
405:     platforms.push({
406:       x: xs[i],
407:       y: floorY - step * (i + 1),
408:       w: w[i],
409:       h: 18 * S,
410:       style: i,
411:       vx: (i % 2 === 0 ? 1 : -1) * rand(40, 110) * S,
412:     });
413:   }
414: 
415:   if (mirror) {
416:     for (const p of platforms) p.x = arena.left + (arena.right - p.x - p.w);
417:   }
418:   for (const p of platforms) {
419:     p.x = clamp(p.x, arena.left + 8, arena.right - p.w - 8);
420:     p.y = Math.max(p.y, arena.top + 54 * S);
421:   }
